(function() {
    'use strict';

    class StratPlanAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Strategic Planning Essentials: El Plan que Funciona';
            this.version = '1.1.0';

            this.SWOT_FACTORS = [
                { id: 1,  correct: 'S' },
                { id: 2,  correct: 'W' },
                { id: 3,  correct: 'O' },
                { id: 4,  correct: 'T' },
                { id: 5,  correct: 'S' },
                { id: 6,  correct: 'W' },
                { id: 7,  correct: 'O' },
                { id: 8,  correct: 'T' },
                { id: 9,  correct: 'S' },
                { id: 10, correct: 'W' },
                { id: 11, correct: 'O' },
                { id: 12, correct: 'T' }
            ];

            this.SMART_ANSWERS = { 1: true, 2: false, 3: true, 4: true, 5: false };

            this.COHERENCE_OPTIMAL = {
                A: { product: 40, digital: 15, marketing: 30, operations: 15 },
                B: { product: 15, digital: 45, marketing: 25, operations: 15 }
            };
        }

        _letter(s) { return s >= 85 ? 'A' : s >= 70 ? 'B' : s >= 55 ? 'C' : s >= 40 ? 'D' : 'F'; }

        _tierSlug(total) { return total >= 85 ? 'estratega' : total >= 70 ? 'solido' : total >= 55 ? 'construccion' : 'rumbo'; }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    totalScore: 0,
                    swotScore: 0,
                    smartIdScore: 0,
                    rewriteScore: 0,
                    justificationScore: 0,
                    coherenceScore: 0,
                    chosenAlternative: '',
                    scoreHistory: [],
                    phaseNames: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = { phase: 1 };
            }
            this._updateBriefing(state);
        }

        _factorText(id, lang) {
            var t = window.mySimulation ? window.mySimulation.t : null;
            if (t) return t('factor_' + id);
            var map = {
                1:  ['18 years of local knowledge of Pacific coast destinations',
                     '18 a\u00f1os de conocimiento local de destinos del Pac\u00edfico'],
                2:  ['Zero digital booking capability — all reservations by phone or email',
                     'Cero capacidad de reservas digitales — todo por tel\u00e9fono o email'],
                3:  ['Growing experiential travel trend among millennials',
                     'Tendencia creciente de turismo vivencial entre millennials'],
                4:  ['Booking.com and Airbnb entering Colombia domestic tourism market',
                     'Booking.com y Airbnb entrando al mercado de turismo dom\u00e9stico colombiano'],
                5:  ['Proprietary network of indigenous and local guides with exclusive relationships',
                     'Red propia de gu\u00edas ind\u00edgenas y locales con relaciones exclusivas'],
                6:  ['Average customer age of 47 — aging customer base with no millennial pipeline',
                     'Edad promedio del cliente: 47 a\u00f1os — base de clientes envejeciendo'],
                7:  ['Post-COVID domestic tourism boom and government infrastructure investment in Pacific Coast',
                     'Boom del turismo dom\u00e9stico post-COVID e inversi\u00f3n gubernamental en infraestructura del Pac\u00edfico'],
                8:  ['Low-cost digital competitors replicating curated packages at lower prices',
                     'Competidores digitales de bajo costo replicando paquetes a menores precios'],
                9:  ['NPS of 72 with strong repeat purchase and referral rate',
                     'NPS de 72 con alta tasa de recompra y referidos'],
                10: ['No mobile app and limited social media presence',
                     'Sin app m\u00f3vil y presencia limitada en redes sociales'],
                11: ['Strategic alliance potential with eco-tourism certification bodies',
                     'Potencial de alianzas estrat\u00e9gicas con organismos de certificaci\u00f3n de ecoturismo'],
                12: ['Dollar fluctuation reducing international tourist spending power',
                     'Fluctuaci\u00f3n del d\u00f3lar reduciendo el poder adquisitivo de turistas internacionales']
            };
            var idx = (lang === 'es') ? 1 : 0;
            return (map[id] || ['',''])[idx];
        }

        _objText(id, lang) {
            var t = window.mySimulation ? window.mySimulation.t : null;
            if (t) return t('obj_' + id);
            var map = {
                1: ['Increase packages sold to the 25-40 segment by 35% by December 2026, measured by signed contracts',
                    'Incrementar paquetes vendidos al segmento 25\u201340 en un 35% para diciembre 2026, medido por contratos firmados'],
                2: ['Improve the digital presence of the company',
                    'Mejorar la presencia digital de la empresa'],
                3: ['Reach revenue of COP $1,850M by fiscal year-end 2027',
                    'Alcanzar facturaci\u00f3n de COP $1.850M al cierre del a\u00f1o fiscal 2027'],
                4: ['Reduce customer acquisition cost by 20% through digital channels by June 2027',
                    'Reducir costo de adquisici\u00f3n de cliente en un 20% mediante canales digitales para junio 2027'],
                5: ['Be leaders in Pacific coast tourism in Colombia',
                    'Ser l\u00edderes en turismo del Pac\u00edfico colombiano']
            };
            var idx = (lang === 'es') ? 1 : 0;
            return (map[id] || ['',''])[idx];
        }

        _getLang() {
            try {
                var html = document.documentElement;
                if (html && html.lang) return html.lang.substring(0, 2);
            } catch(e) {}
            return 'es';
        }

        _updateBriefing(state) {
            var period = state.currentPeriod || 1;
            var lang = this._getLang();
            var t = window.mySimulation ? function(k) { return window.mySimulation.t(k); } : function(k) { return k; };

            var briefEl = document.getElementById('briefingSection');
            var swotEl = document.getElementById('swotSection');
            var objEl = document.getElementById('objectivesSection');
            var altEl = document.getElementById('alternativeSection');
            var budgEl = document.getElementById('budgetSection');
            var phaseEl = document.getElementById('phaseNameDisplay');

            if (briefEl) briefEl.style.display = 'none';
            if (swotEl) swotEl.style.display = 'none';
            if (objEl) objEl.style.display = 'none';
            if (altEl) altEl.style.display = 'none';
            if (budgEl) budgEl.style.display = 'none';

            if (period === 1) {
                if (briefEl) briefEl.style.display = 'block';
                if (swotEl) swotEl.style.display = 'block';
                if (phaseEl) phaseEl.textContent = t('phase_1_name');
                this._buildBriefing(lang, t);
                this._buildSwotUI(lang, t);
            } else if (period === 2) {
                if (objEl) objEl.style.display = 'block';
                if (phaseEl) phaseEl.textContent = t('phase_2_name');
                this._buildObjectivesUI(lang, t);
            } else if (period === 3) {
                if (altEl) altEl.style.display = 'block';
                if (phaseEl) phaseEl.textContent = t('phase_3_name');
                this._buildAlternativesUI(lang, t);
            } else if (period === 4) {
                if (budgEl) budgEl.style.display = 'block';
                if (phaseEl) phaseEl.textContent = t('phase_4_name');
                this._buildBudgetUI(lang, t, state);
            }
        }

        _buildBriefing(lang, t) {
            var el = document.getElementById('briefingContent');
            if (!el) return;
            el.innerHTML = '<p>' + t('briefing_text') + '</p>' +
                '<div class="stratplan-sim-briefing-company">' +
                '<div class="stratplan-sim-briefing-stat"><div class="stat-val">18</div><div class="stat-lbl">' + t('years_operating') + '</div></div>' +
                '<div class="stratplan-sim-briefing-stat"><div class="stat-val">COP $1,420M</div><div class="stat-lbl">' + t('annual_revenue') + '</div></div>' +
                '<div class="stratplan-sim-briefing-stat"><div class="stat-val">72</div><div class="stat-lbl">NPS</div></div>' +
                '<div class="stratplan-sim-briefing-stat"><div class="stat-val">22</div><div class="stat-lbl">' + t('employees') + '</div></div>' +
                '</div>' +
                '<p style="margin-top:15px;font-style:italic;color:#555;">' + t('board_mandate') + '</p>';
        }

        _buildSwotUI(lang, t) {
            var container = document.getElementById('swotFactors');
            if (!container) return;
            var html = '';
            var optLabel = { S: t('strength'), W: t('weakness'), O: t('opportunity'), T: t('threat') };
            for (var i = 0; i < this.SWOT_FACTORS.length; i++) {
                var f = this.SWOT_FACTORS[i];
                var txt = this._factorText(f.id, lang);
                html += '<div class="stratplan-sim-factor-row">' +
                    '<span class="factor-num" style="font-weight:700;color:#2e86c1;min-width:28px;">' + f.id + '.</span>' +
                    '<span class="factor-text">' + txt + '</span>' +
                    '<select id="swot_' + f.id + '" class="form-control">' +
                    '<option value="">— ' + t('classify') + ' —</option>' +
                    '<option value="S">' + optLabel.S + '</option>' +
                    '<option value="W">' + optLabel.W + '</option>' +
                    '<option value="O">' + optLabel.O + '</option>' +
                    '<option value="T">' + optLabel.T + '</option>' +
                    '</select></div>';
            }
            container.innerHTML = html;
        }

        _buildObjectivesUI(lang, t) {
            var container = document.getElementById('objectivesList');
            if (!container) return;
            var html = '';
            for (var i = 1; i <= 5; i++) {
                var txt = this._objText(i, lang);
                html += '<div class="stratplan-sim-obj-row">' +
                    '<input type="checkbox" id="obj_' + i + '" value="' + i + '" style="margin-top:4px;transform:scale(1.3);">' +
                    '<label for="obj_' + i + '">' + txt + '</label></div>';
            }
            container.innerHTML = html;

            var sel = document.getElementById('rewriteSelect');
            if (sel) {
                sel.innerHTML = '<option value="">— ' + t('select_to_rewrite') + ' —</option>' +
                    '<option value="2">' + t('objective') + ' 2: ' + this._objText(2, lang).substring(0, 50) + '...</option>' +
                    '<option value="5">' + t('objective') + ' 5: ' + this._objText(5, lang).substring(0, 50) + '...</option>';
            }
        }

        _buildAlternativesUI(lang, t) {
            var container = document.getElementById('alternativesContent');
            if (!container) return;
            container.innerHTML =
                '<div class="stratplan-sim-alt-card" id="altCardA" onclick="document.getElementById(\'altA\').checked=true;document.querySelectorAll(\'.stratplan-sim-alt-card\').forEach(function(c){c.classList.remove(\'selected\')});this.classList.add(\'selected\');">' +
                '<div style="display:flex;align-items:center;gap:10px;"><input type="radio" name="altChoice" id="altA" value="A"><h4>' + t('alt_a_title') + '</h4></div>' +
                '<p>' + t('alt_a_desc') + '</p>' +
                '<p><strong>' + t('key_assumption') + ':</strong> ' + t('alt_a_assumption') + '</p>' +
                '<p><strong>' + t('risk_level') + ':</strong> ' + t('alt_a_risk') + '</p></div>' +
                '<div class="stratplan-sim-alt-card" id="altCardB" onclick="document.getElementById(\'altB\').checked=true;document.querySelectorAll(\'.stratplan-sim-alt-card\').forEach(function(c){c.classList.remove(\'selected\')});this.classList.add(\'selected\');">' +
                '<div style="display:flex;align-items:center;gap:10px;"><input type="radio" name="altChoice" id="altB" value="B"><h4>' + t('alt_b_title') + '</h4></div>' +
                '<p>' + t('alt_b_desc') + '</p>' +
                '<p><strong>' + t('key_assumption') + ':</strong> ' + t('alt_b_assumption') + '</p>' +
                '<p><strong>' + t('risk_level') + ':</strong> ' + t('alt_b_risk') + '</p></div>';

            var ji = document.getElementById('justificationInput');
            var wc = document.getElementById('wordCount');
            if (ji && wc) {
                ji.addEventListener('input', function() {
                    var words = ji.value.trim().split(/\s+/).filter(function(w) { return w.length > 0; });
                    wc.textContent = words.length + ' ' + (lang === 'es' ? 'palabras' : 'words');
                });
            }
        }

        _buildBudgetUI(lang, t, state) {
            var container = document.getElementById('budgetSliders');
            if (!container) return;
            var cats = [
                { key: 'product', label: t('budget_product') },
                { key: 'digital', label: t('budget_digital') },
                { key: 'marketing', label: t('budget_marketing') },
                { key: 'operations', label: t('budget_operations') }
            ];
            var html = '';
            for (var i = 0; i < cats.length; i++) {
                var c = cats[i];
                html += '<div class="stratplan-sim-slider-group">' +
                    '<label><span>' + c.label + '</span><span id="val_' + c.key + '">$45,000M</span></label>' +
                    '<input type="range" id="slider_' + c.key + '" min="0" max="180" value="45" step="5"></div>';
            }
            container.innerHTML = html;

            var self = this;
            var sliders = ['product', 'digital', 'marketing', 'operations'];
            sliders.forEach(function(key) {
                var slider = document.getElementById('slider_' + key);
                if (slider) {
                    slider.addEventListener('input', function() {
                        self._onBudgetChange(sliders, state);
                    });
                }
            });
            this._onBudgetChange(sliders, state);
        }

        _onBudgetChange(keys, state) {
            var total = 0;
            var alloc = {};
            for (var i = 0; i < keys.length; i++) {
                var sl = document.getElementById('slider_' + keys[i]);
                if (sl) {
                    var v = parseInt(sl.value) || 0;
                    alloc[keys[i]] = v;
                    total += v;
                    var valEl = document.getElementById('val_' + keys[i]);
                    if (valEl) valEl.textContent = '$' + v.toLocaleString() + 'M';
                }
            }
            var rem = 180 - total;
            var remEl = document.getElementById('budgetRemaining');
            if (remEl) {
                remEl.textContent = '$' + rem.toLocaleString() + 'M';
                remEl.style.color = (rem === 0) ? '#27ae60' : (rem < 0) ? '#e74c3c' : '#f39c12';
            }
            this._updateCoherenceIndicator(alloc, state);
        }

        _updateCoherenceIndicator(alloc, state) {
            var alt = '';
            if (state && state.domainState) alt = state.domainState.chosenAlternative;
            if (!alt) return;
            var total = alloc.product + alloc.digital + alloc.marketing + alloc.operations;
            if (total === 0) return;
            var pcts = {
                product: (alloc.product / total) * 100,
                digital: (alloc.digital / total) * 100,
                marketing: (alloc.marketing / total) * 100,
                operations: (alloc.operations / total) * 100
            };
            var opt = this.COHERENCE_OPTIMAL[alt];
            if (!opt) return;
            var diff = 0;
            var keys = ['product', 'digital', 'marketing', 'operations'];
            for (var i = 0; i < keys.length; i++) {
                diff += Math.abs(pcts[keys[i]] - opt[keys[i]]);
            }
            var score = Math.max(0, 100 - diff);
            var bar = document.getElementById('coherenceBar');
            var txt = document.getElementById('coherenceText');
            var cdEl = document.getElementById('coherenceDisplay');
            var color = '#e74c3c';
            var label = '';
            var lang = this._getLang();
            if (score >= 75) { color = '#27ae60'; label = lang === 'es' ? 'Alta coherencia' : 'High coherence'; }
            else if (score >= 50) { color = '#f39c12'; label = lang === 'es' ? 'Coherencia parcial' : 'Partial coherence'; }
            else { color = '#e74c3c'; label = lang === 'es' ? 'Baja coherencia' : 'Low coherence'; }
            if (bar) { bar.style.width = score + '%'; bar.style.background = color; }
            if (txt) { txt.textContent = label; txt.style.color = color; }
            if (cdEl) { cdEl.textContent = Math.round(score) + '%'; cdEl.style.color = color; }
        }

        validateDecisions(decisions) {
            var state = window.mySimulation.state;
            var period = state.currentPeriod || 1;
            var t = function(k) { return window.mySimulation.t(k); };

            if (period === 1) {
                var swotAnswers = {};
                var allFilled = true;
                for (var i = 0; i < this.SWOT_FACTORS.length; i++) {
                    var f = this.SWOT_FACTORS[i];
                    var sel = document.getElementById('swot_' + f.id);
                    if (sel && sel.value) {
                        swotAnswers[f.id] = sel.value;
                    } else {
                        allFilled = false;
                    }
                }
                if (!allFilled) {
                    window.mySimulation.uiManager.showNotification(t('swot_warning'), 'warning');
                    return false;
                }
                decisions.swotAnswers = swotAnswers;
                decisions.phase = 1;
                return true;
            }

