                var rewriteText = rInp ? rInp.value.trim() : '';
                if (!rewriteTarget) {
                    window.mySimulation.uiManager.showNotification(t('rewrite_select_warning'), 'warning');
                    return false;
                }
                if (rewriteText.length < 10) {
                    window.mySimulation.uiManager.showNotification(t('rewrite_text_warning'), 'warning');
                    return false;
                }
                decisions.smartSelections = selected;
                decisions.rewriteTarget = parseInt(rewriteTarget);
                decisions.rewriteText = rewriteText;
                decisions.phase = 2;
                return true;
            }

            if (period === 3) {
                var altA = document.getElementById('altA');
                var altB = document.getElementById('altB');
                var chosen = '';
                if (altA && altA.checked) chosen = 'A';
                if (altB && altB.checked) chosen = 'B';
                if (!chosen) {
                    window.mySimulation.uiManager.showNotification(t('alt_warning'), 'warning');
                    return false;
                }
                var justEl = document.getElementById('justificationInput');
                var justText = justEl ? justEl.value.trim() : '';
                if (justText.length < 15) {
                    window.mySimulation.uiManager.showNotification(t('justify_warning'), 'warning');
                    return false;
                }
                decisions.chosenAlternative = chosen;
                decisions.justificationText = justText;
                decisions.phase = 3;
                return true;
            }

            if (period === 4) {
                var budget = {};
                var bTotal = 0;
                var bKeys = ['product', 'digital', 'marketing', 'operations'];
                for (var k = 0; k < bKeys.length; k++) {
                    var sl = document.getElementById('slider_' + bKeys[k]);
                    budget[bKeys[k]] = sl ? parseInt(sl.value) || 0 : 0;
                    bTotal += budget[bKeys[k]];
                }
                if (bTotal !== 180) {
                    window.mySimulation.uiManager.showNotification(t('budget_total_warning'), 'warning');
                    return false;
                }
                decisions.budgetAllocation = budget;
                decisions.phase = 4;
                return true;
            }

            return true;
        }

        calculateResults(state) {
            var period = state.currentPeriod;
            var d = state.decisions;
            var ds = state.domainState;
            var results = { period: period, phaseScore: 0, phaseName: '', maxScore: 0 };

            if (period === 1) {
                var correct = 0;
                for (var i = 0; i < this.SWOT_FACTORS.length; i++) {
                    var f = this.SWOT_FACTORS[i];
                    if (d.swotAnswers && d.swotAnswers[f.id] === f.correct) correct++;
                }
                var score = Math.round((correct / 12) * 25);
                ds.swotScore = score;
                ds.totalScore += score;
                results.phaseScore = score;
                results.maxScore = 25;
                results.correctCount = correct;
                results.totalFactors = 12;
                results.phaseName = 'SWOT';
            }

            if (period === 2) {
                var smartCorrect = 0;
                if (d.smartSelections) {
                    for (var j = 0; j < d.smartSelections.length; j++) {
                        var selId = d.smartSelections[j];
                        if (this.SMART_ANSWERS[selId] === true) smartCorrect++;
                    }
                }
                var notSelectedCorrect = 0;
                for (var m = 1; m <= 5; m++) {
                    if (d.smartSelections && d.smartSelections.indexOf(m) === -1 && this.SMART_ANSWERS[m] === false) {
                        notSelectedCorrect++;
                    }
                }
                var idScore = Math.round(((smartCorrect + notSelectedCorrect) / 5) * 20);
                ds.smartIdScore = idScore;

                var rwScore = 0;
                if (d.rewriteText && d.rewriteText.length > 0) {
                    var txt = d.rewriteText.toLowerCase();
                    var words = txt.split(/\s+/).filter(function(w) { return w.length > 0; });
                    if (words.length >= 8) rwScore += 3;
                    if (/\d+/.test(txt)) rwScore += 3;
                    if (/202[5-9]|203\d|diciembre|junio|enero|marzo|septiembre|december|june|january/.test(txt)) rwScore += 3;
                    if (d.rewriteTarget === 2 || d.rewriteTarget === 5) rwScore += 3;
                    if (txt !== this._objText(d.rewriteTarget || 2, 'es').toLowerCase() && txt !== this._objText(d.rewriteTarget || 2, 'en').toLowerCase()) rwScore += 3;
                    rwScore = Math.min(rwScore, 15);
                }
                ds.rewriteScore = rwScore;
                var totalPhase = idScore + rwScore;
                ds.totalScore += totalPhase;
                results.phaseScore = totalPhase;
                results.maxScore = 35;
                results.smartCorrect = smartCorrect;
                results.rewriteScore = rwScore;
                results.phaseName = 'SMART';
            }

            if (period === 3) {
                ds.chosenAlternative = d.chosenAlternative || 'A';
                var jScore = 0;
                if (d.justificationText) {
                    var jWords = d.justificationText.trim().split(/\s+/).filter(function(w) { return w.length > 0; });
                    var wLen = jWords.length;
                    if (wLen >= 30 && wLen <= 50) jScore += 5;
                    else if (wLen >= 20) jScore += 3;
                    else if (wLen >= 10) jScore += 2;
                    var jLower = d.justificationText.toLowerCase();
                    var stratTerms = ['swot', 'fortaleza', 'debilidad', 'oportunidad', 'amenaza', 'competencia', 'diferenciaci', 'digital', 'premium', 'gu\u00eda', 'experiencia', 'strength', 'weakness', 'opportunity', 'threat', 'core competence', 'differentiat'];
                    var termHits = 0;
                    for (var s = 0; s < stratTerms.length; s++) {
                        if (jLower.indexOf(stratTerms[s]) !== -1) termHits++;
                    }
                    if (termHits >= 3) jScore += 5;
                    else if (termHits >= 1) jScore += 3;
                    jScore = Math.min(jScore, 10);
                }
                ds.justificationScore = jScore;
                ds.totalScore += jScore;
                results.phaseScore = jScore;
                results.maxScore = 10;
                results.chosenAlternative = ds.chosenAlternative;
                results.phaseName = 'Alternative';
            }

            if (period === 4) {
                var alloc = d.budgetAllocation || { product: 45, digital: 45, marketing: 45, operations: 45 };
                var alt = ds.chosenAlternative || 'A';
                var opt = this.COHERENCE_OPTIMAL[alt];
                var aTotal = alloc.product + alloc.digital + alloc.marketing + alloc.operations;
                var pcts = {
                    product: (alloc.product / aTotal) * 100,
                    digital: (alloc.digital / aTotal) * 100,
                    marketing: (alloc.marketing / aTotal) * 100,
                    operations: (alloc.operations / aTotal) * 100
                };
                var totalDiff = 0;
                var bKeys = ['product', 'digital', 'marketing', 'operations'];
                var offCount = 0;
                for (var b = 0; b < bKeys.length; b++) {
                    var catDiff = Math.abs(pcts[bKeys[b]] - opt[bKeys[b]]);
                    totalDiff += catDiff;
                    if (catDiff > 15) offCount++;
                }
                var cScore = 30;
                if (totalDiff <= 20) cScore = 30;
                else if (totalDiff <= 40) cScore = 22;
                else if (totalDiff <= 60) cScore = 14;
                else cScore = 5;
                ds.coherenceScore = cScore;
                ds.totalScore += cScore;
                results.phaseScore = cScore;
                results.maxScore = 30;
                results.coherenceLevel = cScore >= 28 ? 'full' : cScore >= 20 ? 'mostly' : cScore >= 12 ? 'partial' : 'incoherent';
                results.phaseName = 'Budget';
                results.budgetAllocation = alloc;
            }

            ds.scoreHistory.push(results.phaseScore);
            var _ov = Math.max(0, Math.min(100, Math.round(ds.totalScore)));
            var _tier = this._tierSlug(ds.totalScore);
            ds.performance = { overallScore: _ov, score: _ov, grade: this._letter(_ov), performanceTier: _tier };
            ds.performanceTier = _tier;
            results.overallScore = _ov;
            var lang = this._getLang();
            var phaseNames = {
                1: lang === 'es' ? 'SWOT' : 'SWOT',
                2: lang === 'es' ? 'Objetivos SMART' : 'SMART Objectives',
                3: lang === 'es' ? 'Alternativa' : 'Alternative',
                4: lang === 'es' ? 'Presupuesto' : 'Budget'
            };
            ds.phaseNames.push(phaseNames[period] || ('P' + period));

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: period + 1, domainState: ds });
            }, 500);

            return results;
        }

