            for (var i = 0; i < history.length; i++) {
                total += (history[i].results ? history[i].results.phaseScore : 0) || 0;
            }
            var _t = (window.mySimulation && window.mySimulation.t) ? function(k){ return window.mySimulation.t(k); } : function(k){ return k; };
            var tierSlug = this._tierSlug(total);
            var band = _t('band_' + tierSlug);
            var feedback = _t('feedback_' + tierSlug);
            var overallScore = Math.max(0, Math.min(100, Math.round(total)));
            return {
                totalScore: total,
                overallScore: overallScore,
                grade: this._letter(overallScore),
                performanceTier: tierSlug,
                performance: band,
                insights: [feedback]
            };
        }

        formatCompletionMessage(summary) {
            var _t = (window.mySimulation && window.mySimulation.t) ? function(k){ return window.mySimulation.t(k); } : function(k){ return k; };
